import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CdTmk4Xw.js";const k=JSON.parse('{"title":"开发工具","description":"","frontmatter":{"editLink":true},"headers":[],"relativePath":"tooling.md","filePath":"tooling.md"}'),s={name:"tooling.md"};function i(r,e,c,p,n,l){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="开发工具" tabindex="-1">开发工具 <a class="header-anchor" href="#开发工具" aria-label="Permalink to &quot;开发工具&quot;">​</a></h1><p>单题编译不依赖编辑器插件；可先按<a href="./quick-start.html">快速开始</a>确认编译器。以下工具是当前仓库已有的可选工作流。</p><h2 id="vs-code-cph" tabindex="-1">VS Code / CPH <a class="header-anchor" href="#vs-code-cph" aria-label="Permalink to &quot;VS Code / CPH&quot;">​</a></h2><p><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/.vscode/settings.json" target="_blank" rel="noreferrer">settings.json</a> 定义默认语言、模板位置、保存目录、文件名模板和 OJ URL 映射。迁移到其他机器时，先检查这些设置：</p><table tabindex="0"><thead><tr><th>设置</th><th>需要适配的内容</th></tr></thead><tbody><tr><td><code>cph.general.defaultLanguageTemplateFileLocation</code></td><td>本机仓库内 <code>Templates/templates/cph.cpp</code> 的绝对路径</td></tr><tr><td><code>cph.general.saveLocation</code></td><td>本机仓库 <code>.cph</code> 的绝对路径</td></tr><tr><td><code>cph.general.fileNameTemplate</code> / <code>fileNameTemplateOverrides</code></td><td>目标 OJ 的目录与题号规则</td></tr><tr><td><code>cph.general.ojMapping</code></td><td>URL 正则和来源名称；与 relay 的规则分别维护</td></tr></tbody></table><p>当前配置包含 ShortestPath 规则，但源快照不含 <code>ShortestPath/</code> 目录；配置存在不代表已有此平台题解。不同版本插件是否识别这些设置，需要在本机扩展中核对。</p><p><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/.vscode/tasks.json" target="_blank" rel="noreferrer">tasks.json</a> 只编译活动文件，使用 GNU++23 和一个仓库外的个人编译 wrapper。换机器后把 <code>command</code> 改为真实 GNU C++ 编译器，移除不适用于当前架构的 CPU 参数，再检查输出路径；仓库没有提供该 wrapper，不能原样执行就假定可用。</p><p>本机路径调整属于个人配置；提交前检查差异，避免把另一台机器的绝对路径覆盖为自己的路径。</p><h2 id="competitive-companion-relay" tabindex="-1">Competitive Companion relay <a class="header-anchor" href="#competitive-companion-relay" aria-label="Permalink to &quot;Competitive Companion relay&quot;">​</a></h2><p><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/.cph/scripts/competitive-companion-relay.mjs" target="_blank" rel="noreferrer">relay 脚本</a> 使用 Node.js 内置模块，无 npm 包依赖。它接收题目导入请求，匹配来源路径、生成或迁移源码、处理 <code>.prob</code> 元数据，并可打开编辑器。</p><p>从仓库根目录手动启动，默认端口为 <code>4243</code>：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CC_RELAY_REPO_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CC_RELAY_DISABLE_OPEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .cph/scripts/competitive-companion-relay.mjs</span></span></code></pre></div><p>在另一终端检查服务是否已响应：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4243/</span></span></code></pre></div><p>GET 响应包含 <code>ok</code>、端口和仓库位置；POST 的 <code>ok</code> 仅表示任务已入队，完成情况以日志和实际文件为准。导入方需要把请求发送到同一端口。结束前台服务使用 <code>Ctrl+C</code>。</p><table tabindex="0"><thead><tr><th>环境变量</th><th>默认或用途</th></tr></thead><tbody><tr><td><code>CC_RELAY_REPO_ROOT</code></td><td>默认取用户目录下的 <code>Developer/CompetitiveProgramming</code>；建议显式指定</td></tr><tr><td><code>CC_RELAY_CODE_CLI</code></td><td>默认是 macOS VS Code CLI 的应用内路径</td></tr><tr><td><code>CC_RELAY_TEMPLATE_FILE</code></td><td>默认仓库内 <code>Templates/templates/cph.cpp</code></td></tr><tr><td><code>CC_RELAY_PORT</code></td><td><code>4243</code></td></tr><tr><td><code>CC_RELAY_POLL_TIMEOUT_MS</code></td><td><code>2500</code>，等待导入文件的轮询时限</td></tr><tr><td><code>CC_RELAY_DISABLE_OPEN</code></td><td>设为 <code>1</code> 时不自动打开编辑器</td></tr></tbody></table><p>导入会写文件，并可能移动或删除临时源码、清理重复 <code>.prob</code>；<code>CC_RELAY_DISABLE_OPEN=1</code> 只关闭打开编辑器，不关闭这些写操作。当前服务没有指定监听地址，不能将它描述为仅绑定回环地址；应在受信任的本机环境运行，并核对实际监听端口。</p><h2 id="macos-常驻配置" tabindex="-1">macOS 常驻配置 <a class="header-anchor" href="#macos-常驻配置" aria-label="Permalink to &quot;macOS 常驻配置&quot;">​</a></h2><p><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/.cph/scripts/com.l7.competitive-companion-relay.plist" target="_blank" rel="noreferrer">LaunchAgent 配置</a> 记录了 Node、脚本、工作目录和日志的个人绝对路径，并启用了 <code>RunAtLoad</code> / <code>KeepAlive</code>。克隆仓库不会安装该服务。</p><p>需要常驻运行时，先验证上面的手动启动，再按本机路径制作并检查 LaunchAgent；不要直接套用别人的路径或同时启动两个同端口实例。查看启动问题时先确认端口占用、Node 路径、模板文件和日志。</p><h2 id="本地数据" tabindex="-1">本地数据 <a class="header-anchor" href="#本地数据" aria-label="Permalink to &quot;本地数据&quot;">​</a></h2><p><code>.prob</code>、样例、编译产物和日志默认不跟踪，见 <a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/.gitignore" target="_blank" rel="noreferrer"><code>.gitignore</code></a>。导入后检查源码目标路径、原题链接、已有文件是否受到影响，再进行编译和样例验证。</p>`,22)])])}const g=t(s,[["render",i]]);export{k as __pageData,g as default};
